"""Event replay: folds events.jsonl into per-sku quantities.

Correctness requirement: event_ids must be unique in the stream. If the same
event_id appears more than once (duplicated delivery), it is counted ONCE --
the first occurrence wins; later occurrences with an already-seen id are
ignored.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def load_events(path):
    events = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                events.append(json.loads(line))
    return events


def replay(events):
    """Fold events into {sku: quantity}, deduping by event_id."""
    state = {}
    seen = set()
    for e in sorted(events, key=lambda e: (e["ts"], e["event_id"])):
        eid = e["event_id"]
        if eid in seen:
            continue
        seen.add(eid)
        state[e["sku"]] = state.get(e["sku"], 0) + e["delta"]
    return state


def replay_file(path=None):
    path = Path(path) if path else ROOT / "events.jsonl"
    return replay(load_events(path))


if __name__ == "__main__":
    print(json.dumps(replay_file(), indent=2, sort_keys=True))

